package dev.genericpayments.platform.payments.adapter.in.web;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dev.genericpayments.platform.partners.PartnerTestFixture;
import tools.jackson.databind.ObjectMapper;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.context.WebApplicationContext;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class PaymentOpenApiIntegrationTest extends PartnerTestFixture {
 @Autowired WebApplicationContext context;@Autowired ObjectMapper mapper;
 @Test void exactAdminRoutesAndPreviousOperationsAppearOnce()throws Exception{var mvc=MockMvcBuilders.webAppContextSetup(context).build();var doc=mapper.readTree(mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());var paths=doc.path("paths");var expected=Map.of("/api/v1/admin/payments","listAdminPayments","/api/v1/admin/payments/{paymentId}","getAdminPayment","/api/v1/admin/payments/{paymentId}/refunds","createAdminRefund","/api/v1/admin/payments/{paymentId}/reconcile","reconcileAdminPayment","/api/v1/admin/payments/{paymentId}/fake-events","simulateAdminFakeEvent");expected.forEach((path,id)->assertThat(paths.path(path).path(path.endsWith("refunds")||path.endsWith("reconcile")||path.endsWith("fake-events")?"post":"get").path("operationId").asText()).isEqualTo(id));String text=doc.toString();for(String id:List.of("createCatalogCheckout","confirmCheckout","getCheckout","retryAdminOutboxEvent","configureAdminSiteCallback","rotateAdminSiteCallbackSecret"))assertThat(text).contains("\"operationId\":\""+id+"\"");for(String id:expected.values())assertThat(text.split("\"operationId\":\""+id+"\"",-1)).hasSize(2);}
 @Test void headersBoundsClosedEnumsAndProblemFieldsAreDocumented()throws Exception{var mvc=MockMvcBuilders.webAppContextSetup(context).build();var doc=mapper.readTree(mvc.perform(get("/v3/api-docs")).andReturn().getResponse().getContentAsString());var paths=doc.path("paths");for(String suffix:List.of("refunds","reconcile","fake-events")){var op=paths.path("/api/v1/admin/payments/{paymentId}/"+suffix).path("post");boolean header=false;for(var parameter:op.path("parameters"))if(parameter.path("name").asText().equals("Idempotency-Key")){header=true;assertThat(parameter.path("required").asBoolean()).isTrue();assertThat(parameter.path("in").asText()).isEqualTo("header");assertThat(parameter.path("schema").path("maxLength").asInt()).isEqualTo(255);}assertThat(header).isTrue();assertThat(op.path("responses").path("400").toString()).contains("ApiProblem");if(!suffix.equals("reconcile"))assertThat(op.path("responses").has("202")).isTrue();}
 var params=paths.path("/api/v1/admin/payments").path("get").path("parameters");var names=new HashSet<String>();for(var param:params){names.add(param.path("name").asText());if(param.path("name").asText().equals("size"))assertThat(param.path("schema").path("maximum").asInt()).isEqualTo(100);}assertThat(names).contains("site_id","status","external_order_id","payment_id","provider","created_from","created_to","page","size","sort");var schemas=doc.path("components").path("schemas");assertThat(schemas.path("FakeRequest").toString()).contains("event_type");assertThat(schemas.path("FakeRequest").path("properties").path("event_type").path("enum").toString()).doesNotContain("PAYMENT_CREATED","REFUND_REQUESTED","PROVIDER_RESULT_UNKNOWN").contains("REFUND_SUCCEEDED","PAYMENT_SUCCEEDED");assertThat(schemas.path("FakeRequest").path("properties").path("target").path("enum").toString()).contains("PAYMENT","REFUND");assertThat(schemas.path("ApiValidationProblem").path("properties").has("field_errors")).isTrue();assertThat(schemas.path("Projection").path("properties").path("status").path("enum").toString()).contains("SUCCEEDED","PARTIALLY_REFUNDED","REFUNDED");}
 @Test void everyNewResponseVocabularyIsClosed()throws Exception{var mvc=MockMvcBuilders.webAppContextSetup(context).build();var schemas=mapper.readTree(mvc.perform(get("/v3/api-docs")).andReturn().getResponse().getContentAsString()).path("components").path("schemas");for(var pair:Map.of("Outbox","status","Delivery","error_category","Accepted","status").entrySet())assertThat(schemas.path(pair.getKey()).path("properties").path(pair.getValue()).has("enum")).as(pair.toString()).isTrue();}
}
